def block_feats(b):
    n=4
    total=sum(v!=0 for r in b for v in r)
    # comps
    seen=set(); comps=[]
    for i in range(n):
        for j in range(n):
            if b[i][j]!=0 and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=0
                while st:
                    y,x=st.pop(); c+=1
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<n and 0<=nx<n and b[ny][nx]!=0 and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                comps.append(c)
    erows=sum(all(v==0 for v in r) for r in b)
    ecols=sum(all(b[i][j]==0 for i in range(n)) for j in range(n))
    return dict(total=total, ncomp=len(comps), maxcomp=max(comps), mincomp=min(comps), erows=erows, ecols=ecols)

