    n=4
    # 2x2 window count containing cell (of nonzero)
    for i in range(n):
        for j in range(n):
            if (i,j) not in F: continue
            c2=0
            for di in(-1,0):
                for dj in(-1,0):
                    cells=[(i+di+a, j+dj+bb) for a in range(2) for bb in range(2)]
                    if all(0<=y<n and 0<=x<n and b[y][x]!=0 for y,x in cells): c2+=1
            F[(i,j)]['sq2']=c2
            # bbox of block
            ys=[y for y in range(n) for x in range(n) if b[y][x]!=0]
            xs=[x for y in range(n) for x in range(n) if b[y][x]!=0]
            F[(i,j)]['bbar']=sum(ys)/len(ys); F[(i,j)]['bbac']=sum(xs)/len(xs)
            F[(i,j)]['bbar2']=(i-sum(ys)/len(ys))**2+(j-sum(xs)/len(xs))**2
